def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row), key=lambda x: sum(r.count(x) for r in grid))
    seed_row = next(r for r, row in enumerate(grid) if 3 in row and 8 in row)
    cols = [c for c, v in enumerate(grid[seed_row]) if v != bg]
    start, end = min(cols), max(cols)
    motif = grid[seed_row][start:end + 1]

    out = [row[:] for row in grid]
    for r in range(h):
        if r == seed_row:
            continue
        for c, v in enumerate(grid[r]):
            if v == 2 or (v == 6 and seed_row == h - 1):
                left = c - len(motif) // 2
                for i, color in enumerate(motif):
                    cc = left + i
                    if 0 <= cc < w:
                        out[r][cc] = color
    return out
